with kept_keys as (select promo_code, channel from promotions except distinct select promo_code, channel from promotions where year(ends_on) = 2025), verified as (select s.* from promotions s inner join kept_keys k on s.promo_code = k.promo_code and s.channel = k.channel) select id, channel, promo_code, starts_on, ends_on, discount_pct, case when promo_code rlike '^(BUNDLE|SPRING10)$' then 'CORE' else 'PRIORITY' end as promo_code_zone from verified order by discount_pct desc;
